import type { KeyboardEvent, RefObject } from "react";
import type { Agent } from "../../types";
import ChatModeHint from "./ChatModeHint";

type ChatMode = "chat" | "task" | "announcement" | "report" | "question";
type Tr = (ko: string, en: string, ja?: string, zh?: string) => string;

interface ChatComposerProps {
  allowGlobalTasks?: boolean;
  mode: ChatMode;
  input: string;
  selectedAgent: Agent | null;
  isDirectiveMode: boolean;
  isAnnouncementMode: boolean;
  tr: Tr;
  getAgentName: (agent: Agent | null | undefined) => string;
  textareaRef: RefObject<HTMLTextAreaElement | null>;
  onModeChange: (mode: ChatMode) => void;
  onInputChange: (value: string) => void;
  onSend: () => void;
  onKeyDown: (event: KeyboardEvent<HTMLTextAreaElement>) => void;
}

export default function ChatComposer({
  mode,
  input,
  selectedAgent,
  isDirectiveMode,
  isAnnouncementMode,
  tr,
  getAgentName,
  textareaRef,
  onModeChange,
  onInputChange,
  onSend,
  onKeyDown,
  allowGlobalTasks=false,
}: ChatComposerProps) {
  return (
    <>
      <div className="flex flex-shrink-0 gap-2 border-t border-gray-700/50 px-4 pb-1 pt-3">{allowGlobalTasks && <><button className="flex-1 rounded-lg border px-2 py-1.5 text-xs" onClick={()=>onModeChange("chat")} aria-pressed={mode==="chat"}>대화</button><button className="flex-1 rounded-lg border px-2 py-1.5 text-xs" onClick={()=>onModeChange("question")} aria-pressed={mode==="question"}>질문</button></>}
        <button
          onClick={() => onModeChange(mode === "task" ? "chat" : "task")}
          disabled={!selectedAgent && !allowGlobalTasks}
          className={`flex flex-1 items-center justify-center gap-1 rounded-lg px-2 py-1.5 text-xs font-medium transition-colors ${
            mode === "task"
              ? "bg-blue-600 text-white"
              : "bg-gray-700 text-gray-300 hover:bg-gray-600 disabled:cursor-not-allowed disabled:opacity-40"
          }`}
        >
          <span>📋</span>
          <span>{tr("업무 지시", "Task", "タスク指示", "任务指示")}</span>
        </button>

        <button
          onClick={() => onModeChange(mode === "announcement" ? "chat" : "announcement")}
          className={`flex flex-1 items-center justify-center gap-1 rounded-lg px-2 py-1.5 text-xs font-medium transition-colors ${
            mode === "announcement" ? "bg-yellow-500 text-gray-900" : "bg-gray-700 text-gray-300 hover:bg-gray-600"
          }`}
        >
          <span>📢</span>
          <span>{tr("전사 공지", "Announcement", "全体告知", "全员公告")}</span>
        </button>

        {!allowGlobalTasks && <button
          onClick={() => onModeChange(mode === "report" ? "chat" : "report")}
          disabled={!selectedAgent && !allowGlobalTasks}
          className={`flex flex-1 items-center justify-center gap-1 rounded-lg px-2 py-1.5 text-xs font-medium transition-colors ${
            mode === "report"
              ? "bg-emerald-600 text-white"
              : "bg-gray-700 text-gray-300 hover:bg-gray-600 disabled:cursor-not-allowed disabled:opacity-40"
          }`}
        >
          <span>📊</span>
          <span>{tr("보고 요청", "Report", "レポート依頼", "报告请求")}</span>
        </button>}
      </div>

      <ChatModeHint mode={mode === "question" ? "chat" : mode} isDirectiveMode={isDirectiveMode} tr={tr} />

      <div className="flex-shrink-0 px-4 pb-4 pt-2">
        <div
          className={`flex items-end gap-2 rounded-2xl border bg-gray-800 transition-colors ${
            isDirectiveMode
              ? "border-red-500/50 focus-within:border-red-400"
              : isAnnouncementMode
                ? "border-yellow-500/50 focus-within:border-yellow-400"
                : mode === "task"
                  ? "border-blue-500/50 focus-within:border-blue-400"
                  : mode === "report"
                    ? "border-emerald-500/50 focus-within:border-emerald-400"
                    : "border-gray-600 focus-within:border-blue-500"
          }`}
        >
          <textarea
            ref={textareaRef}
            value={input}
            onChange={(e) => onInputChange(e.target.value)}
            onKeyDown={onKeyDown}
            placeholder={
              isAnnouncementMode
                ? tr(
                    "전사 공지 내용을 입력하세요...",
                    "Write an announcement...",
                    "全体告知内容を入力してください...",
                    "请输入公告内容...",
                  )
                : mode === "task"
                  ? tr(
                      "업무 지시 내용을 입력하세요...",
                      "Write a task instruction...",
                      "タスク指示内容を入力してください...",
                      "请输入任务指示内容...",
                    )
                  : mode === "report"
                    ? tr(
                        "보고 요청 내용을 입력하세요...",
                        "Write a report request...",
                        "レポート依頼内容を入力してください...",
                        "请输入报告请求内容...",
                      )
                    : selectedAgent
                      ? tr(
                          `${getAgentName(selectedAgent)}에게 메시지 보내기...`,
                          `Send a message to ${getAgentName(selectedAgent)}...`,
                          `${getAgentName(selectedAgent)}にメッセージを送る...`,
                          `向 ${getAgentName(selectedAgent)} 发送消息...`,
                        )
                      : tr(
                          "메시지를 입력하세요...",
                          "Type a message...",
                          "メッセージを入力してください...",
                          "请输入消息...",
                        )
            }
            rows={1}
            className="min-h-[44px] max-h-32 flex-1 resize-none overflow-y-auto bg-transparent px-4 py-3 text-sm leading-relaxed text-gray-100 placeholder-gray-500 focus:outline-none"
            style={{ scrollbarWidth: "none" }}
            onInput={(e) => {
              const el = e.currentTarget;
              el.style.height = "auto";
              el.style.height = `${Math.min(el.scrollHeight, 128)}px`;
            }}
          />
          <button
            onClick={onSend}
            disabled={!input.trim()}
            className={`mb-2 mr-2 flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-xl transition-all ${
              input.trim()
                ? isDirectiveMode
                  ? "bg-red-600 text-white hover:bg-red-500"
                  : isAnnouncementMode
                    ? "bg-yellow-500 text-gray-900 hover:bg-yellow-400"
                    : mode === "task"
                      ? "bg-blue-600 text-white hover:bg-blue-500"
                      : mode === "report"
                        ? "bg-emerald-600 text-white hover:bg-emerald-500"
                        : "bg-blue-600 text-white hover:bg-blue-500"
                : "cursor-not-allowed bg-gray-700 text-gray-600"
            }`}
            aria-label={tr("전송", "Send", "送信", "发送")}
          >
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="h-4 w-4">
              <path d="M3.478 2.405a.75.75 0 00-.926.94l2.432 7.905H13.5a.75.75 0 010 1.5H4.984l-2.432 7.905a.75.75 0 00.926.94 60.519 60.519 0 0018.445-8.986.75.75 0 000-1.218A60.517 60.517 0 003.478 2.405z" />
            </svg>
          </button>
        </div>
        <p className="mt-1.5 px-1 text-xs text-gray-600">
          {tr(
            "Enter로 전송, Shift+Enter로 줄바꿈",
            "Press Enter to send, Shift+Enter for a new line",
            "Enterで送信、Shift+Enterで改行",
            "按 Enter 发送，Shift+Enter 换行",
          )}
        </p>
      </div>
    </>
  );
}

import { useEffect, useMemo, useState } from "react";
import type { UiLanguage } from "../i18n";
import { pickLang } from "../i18n";
import type { Agent } from "../types";
import AgentAvatar, { buildSpriteMap } from "./AgentAvatar";
import MessageContent from "./MessageContent";
import type { DecisionInboxItem } from "./chat/decision-inbox";
import { formatDecisionInboxTime as formatTime, type DecisionInboxModalProps } from "./chat/decision-inbox-modal.meta";

export default function DecisionInboxModal({
  open,
  loading,
  items,
  agents,
  busyKey,
  uiLanguage,
  onClose,
  onRefresh,
  onReplyOption,
  onOpenChat,
}: DecisionInboxModalProps) {
  const t = (text: { ko: string; en: string; ja?: string; zh?: string }) => pickLang(uiLanguage, text);
  const [officeReportBusy,setOfficeReportBusy]=useState<string|null>(null);
  const [officeReportNotices,setOfficeReportNotices]=useState<Record<string,string>>({});
  const isKorean = uiLanguage.startsWith("ko");
  const spriteMap = useMemo(() => buildSpriteMap(agents), [agents]);
  const agentById = useMemo(() => {
    const map = new Map<string, Agent>();
    for (const agent of agents) map.set(agent.id, agent);
    return map;
  }, [agents]);
  const [followupTarget, setFollowupTarget] = useState<{
    itemId: string;
    optionNumber: number;
  } | null>(null);
  const [followupDraft, setFollowupDraft] = useState("");
  const [reviewPickSelections, setReviewPickSelections] = useState<Record<string, number[]>>({});
  const [reviewPickDrafts, setReviewPickDrafts] = useState<Record<string, string>>({});

  useEffect(() => {
    if (!open) {
      setFollowupTarget(null);
      setFollowupDraft("");
      setReviewPickSelections({});
      setReviewPickDrafts({});
      return;
    }
    if (!followupTarget) return;
    const stillExists = items.some((entry) => entry.id === followupTarget.itemId);
    if (!stillExists) {
      setFollowupTarget(null);
      setFollowupDraft("");
    }
  }, [open, followupTarget, items]);

  useEffect(() => {
    setReviewPickSelections((prev) => {
      const keep = new Set(items.map((item) => item.id));
      const next: Record<string, number[]> = {};
      let changed = false;
      for (const [itemId, nums] of Object.entries(prev)) {
        if (!keep.has(itemId)) {
          changed = true;
          continue;
        }
        next[itemId] = nums;
      }
      return changed ? next : prev;
    });
    setReviewPickDrafts((prev) => {
      const keep = new Set(items.map((item) => item.id));
      const next: Record<string, string> = {};
      let changed = false;
      for (const [itemId, draft] of Object.entries(prev)) {
        if (!keep.has(itemId)) {
          changed = true;
          continue;
        }
        next[itemId] = draft;
      }
      return changed ? next : prev;
    });
  }, [items]);

  const followupItem = useMemo(
    () => (followupTarget ? (items.find((entry) => entry.id === followupTarget.itemId) ?? null) : null),
    [followupTarget, items],
  );
  const followupBusyKey = followupTarget ? `${followupTarget.itemId}:${followupTarget.optionNumber}` : null;
  const isFollowupSubmitting = followupBusyKey ? busyKey === followupBusyKey : false;
  const canSubmitFollowup = !!(followupItem && followupDraft.trim() && !isFollowupSubmitting);

  function handleOptionClick(item: DecisionInboxItem, optionNumber: number, action?: string) {
    if (action === "add_followup_request") {
      setFollowupTarget({ itemId: item.id, optionNumber });
      setFollowupDraft("");
      return;
    }
    onReplyOption(item, optionNumber);
  }

  function handleSubmitFollowup() {
    if (!followupItem || !followupTarget) return;
    const note = followupDraft.trim();
    if (!note) return;
    onReplyOption(followupItem, followupTarget.optionNumber, { note });
    setFollowupTarget(null);
    setFollowupDraft("");
  }

  function handleCancelFollowup() {
    setFollowupTarget(null);
    setFollowupDraft("");
  }

  function getReviewPickOptions(item: DecisionInboxItem) {
    return item.options.filter((option) => option.action === "apply_review_pick");
  }

  function getReviewSkipOption(item: DecisionInboxItem) {
    return item.options.find((option) => option.action === "skip_to_next_round");
  }

  function toggleReviewPick(itemId: string, optionNumber: number) {
    setReviewPickSelections((prev) => {
      const current = prev[itemId] ?? [];
      const exists = current.includes(optionNumber);
      const nextList = exists
        ? current.filter((num) => num !== optionNumber)
        : [...current, optionNumber].sort((a, b) => a - b);
      return {
        ...prev,
        [itemId]: nextList,
      };
    });
  }

  function setReviewDraft(itemId: string, value: string) {
    setReviewPickDrafts((prev) => ({
      ...prev,
      [itemId]: value,
    }));
  }

  function clearReviewInput(itemId: string) {
    setReviewPickSelections((prev) => {
      if (!(itemId in prev)) return prev;
      const next = { ...prev };
      delete next[itemId];
      return next;
    });
    setReviewPickDrafts((prev) => {
      if (!(itemId in prev)) return prev;
      const next = { ...prev };
      delete next[itemId];
      return next;
    });
  }

  function handleSubmitReviewPick(item: DecisionInboxItem) {
    const pickOptions = getReviewPickOptions(item);
    const selected = reviewPickSelections[item.id] ?? [];
    const extraNote = (reviewPickDrafts[item.id] ?? "").trim();
    const optionNumber = selected[0] ?? pickOptions[0]?.number;
    if (!optionNumber) return;
    if (selected.length <= 0 && !extraNote) {
      window.alert(
        t({
          ko: "최소 1개 선택하거나 추가 의견을 입력해 주세요.",
          en: "Pick at least one option or enter an extra note.",
          ja: "少なくとも1件を選択するか、追加意見を入力してください。",
          zh: "请至少选择一项或输入补充意见。",
        }),
      );
      return;
    }
    onReplyOption(item, optionNumber, {
      selected_option_numbers: selected,
      ...(extraNote ? { note: extraNote } : {}),
    });
    clearReviewInput(item.id);
  }

  function handleSkipReviewRound(item: DecisionInboxItem) {
    const skipOption = getReviewSkipOption(item);
    if (!skipOption) return;
    clearReviewInput(item.id);
    onReplyOption(item, skipOption.number);
  }

  const getKindLabel = (kind: DecisionInboxItem["kind"]) => {
    if (kind === "project_review_ready") {
      return t({ ko: "프로젝트 의사결정", en: "Project Decision", ja: "プロジェクト判断", zh: "项目决策" });
    }
    if (kind === "task_timeout_resume") {
      return t({ ko: "중단 작업 재개", en: "Timeout Resume", ja: "中断タスク再開", zh: "超时任务续跑" });
    }
    if (kind === "review_round_pick") {
      return t({
        ko: "리뷰 라운드 의사결정",
        en: "Review Round Decision",
        ja: "レビューラウンド判断",
        zh: "评审轮次决策",
      });
    }
    return t({ ko: "에이전트 요청", en: "Agent Request", ja: "エージェント要請", zh: "代理请求" });
  };
  const getKindAvatarFallback = (kind: DecisionInboxItem["kind"]) => {
    if (kind === "project_review_ready") return "🧑‍💼";
    if (kind === "task_timeout_resume") return "⏱️";
    if (kind === "review_round_pick") return "🧾";
    return "🤖";
  };

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm" onClick={onClose}>
      <div
        className="relative mx-4 w-full max-w-3xl rounded-2xl border border-indigo-500/30 bg-slate-900 shadow-2xl shadow-indigo-500/10"
        onClick={(event) => event.stopPropagation()}
      >
        <div className="flex items-center justify-between border-b border-slate-700/50 px-6 py-4">
          <div className="flex items-center gap-3">
            <span className="text-2xl">🧭</span>
            <h2 className="text-lg font-bold text-white">
              {t({ ko: "미결 의사결정", en: "Pending Decisions", ja: "未決の意思決定", zh: "待处理决策" })}
            </h2>
            <span className="rounded-full bg-indigo-500/20 px-2 py-0.5 text-xs font-medium text-indigo-300">
              {items.length}
            </span>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={onRefresh}
              className="rounded-lg border border-slate-700 px-3 py-1.5 text-xs text-slate-300 transition hover:bg-slate-800 hover:text-white"
            >
              {t({ ko: "새로고침", en: "Refresh", ja: "更新", zh: "刷新" })}
            </button>
            <button
              onClick={onClose}
              className="flex h-8 w-8 items-center justify-center rounded-lg text-slate-400 transition hover:bg-slate-800 hover:text-white"
            >
              ✕
            </button>
          </div>
        </div>

        <div className="max-h-[70vh] overflow-y-auto p-4">
          {loading ? (
            <div className="py-12 text-center text-sm text-slate-500">
              {t({
                ko: "미결 목록 불러오는 중...",
                en: "Loading pending decisions...",
                ja: "未決一覧を読み込み中...",
                zh: "正在加载待处理决策...",
              })}
            </div>
          ) : items.length === 0 ? (
            <div className="py-12 text-center text-sm text-slate-500">
              {t({
                ko: "현재 미결 의사결정이 없습니다.",
                en: "No pending decisions right now.",
                ja: "現在、未決の意思決定はありません。",
                zh: "当前没有待处理决策。",
              })}
            </div>
          ) : (
            <div className="space-y-3">
              {items.map((item) => item.id.startsWith("office-report:") ? <div key={item.id} data-office-report-card className="rounded-xl border border-slate-600 bg-slate-800 p-4">
  <h3 className="text-base font-semibold text-white">{item.projectName || item.agentNameKo || item.agentName || "검토 보고서"}</h3>
  <p className="mb-3 text-xs text-slate-400">저장된 보고서 원문입니다. 읽는 데 에이전트 준비나 새 AI 실행은 필요하지 않습니다.</p>
  <div className="max-h-96 overflow-y-auto rounded-lg bg-slate-900 p-3"><MessageContent content={item.requestContent}/></div>
  <p role="status" className="my-2 text-sm text-amber-300">{officeReportNotices[item.id]}</p>
  <button disabled={officeReportBusy===item.id||!item.taskId} className="mt-2 rounded-lg bg-blue-600 px-4 py-2 text-sm text-white disabled:opacity-50" onClick={async()=>{
    if(!item.taskId||!window.confirm("보고서를 읽고 확인 완료로 기록할까요? 새 개발·회의·AI 업무를 시작하지 않습니다."))return;
    setOfficeReportBusy(item.id);
    try{
      const sessionResponse=await fetch('/control-api/session',{credentials:'same-origin',cache:'no-store'});if(!sessionResponse.ok)throw Error();const session=await sessionResponse.json();
      const taskResponse=await fetch('/control-api/tasks',{credentials:'same-origin',cache:'no-store'});if(!taskResponse.ok)throw Error();const result=await taskResponse.json();const current=result.tasks.find((t:{id:string})=>t.id===item.taskId);
      if(!current?.reportHash||current.result!==item.requestContent)throw Error();
      const accepted=await fetch('/control-api/tasks/'+encodeURIComponent(item.taskId)+'/accept',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json','x-control-csrf':session.csrf},body:JSON.stringify({reportHash:current.reportHash,confirmation:true})});if(!accepted.ok)throw Error();
      setOfficeReportNotices(old=>({...old,[item.id]:'보고서 확인을 기록했습니다.'}));onRefresh();
    }catch{setOfficeReportNotices(old=>({...old,[item.id]:'보고서가 변경됐거나 완료 조건을 확인하지 못했습니다. 새로고침 후 다시 읽어주세요.'}));}finally{setOfficeReportBusy(null);}
  }}>보고서 확인 완료</button>
</div> :
 (
                <div key={item.id} className="rounded-xl border border-slate-700/60 bg-slate-800/50 p-3">
                  <div className="mb-2 flex flex-wrap items-center justify-between gap-2">
                    {(() => {
                      const agent = item.agentId ? agentById.get(item.agentId) : undefined;
                      return (
                        <div className="flex min-w-0 items-start gap-2">
                          {agent ? (
                            <AgentAvatar
                              agent={agent}
                              spriteMap={spriteMap}
                              size={32}
                              className="mt-0.5 border border-slate-600 bg-slate-900"
                            />
                          ) : (
                            <span className="mt-0.5 inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-full border border-slate-600 bg-slate-900 text-base">
                              {item.agentAvatar || getKindAvatarFallback(item.kind)}
                            </span>
                          )}
                          <div className="min-w-0">
                            <p className="truncate text-sm font-semibold text-white">
                              {isKorean ? item.agentNameKo : item.agentName}
                            </p>
                            <p className="text-[11px] text-indigo-300/90">{getKindLabel(item.kind)}</p>
                            <p className="text-[11px] text-slate-400">{formatTime(item.createdAt, uiLanguage)}</p>
                          </div>
                        </div>
                      );
                    })()}
                    {item.agentId ? (
                      <button
                        onClick={() => onOpenChat(item.agentId!)}
                        className="rounded-md border border-slate-600 px-2 py-1 text-[11px] text-slate-300 transition hover:border-slate-400 hover:bg-slate-700 hover:text-white"
                      >
                        {t({ ko: "채팅 열기", en: "Open Chat", ja: "チャットを開く", zh: "打开聊天" })}
                      </button>
                    ) : null}
                  </div>

                  <div className="rounded-lg border border-slate-700/70 bg-slate-900/60 px-2.5 py-2 text-xs text-slate-200">
                    <MessageContent content={item.requestContent} />
                  </div>

                  <div className="mt-2 space-y-1.5">
                    {item.kind === "review_round_pick" ? (
                      (() => {
                        if (item.options.length === 0) {
                          return (
                            <p className="rounded-md border border-slate-700/70 bg-slate-900/50 px-2.5 py-2 text-xs text-slate-400">
                              {t({
                                ko: "기획팀장 의견 취합중...",
                                en: "Planning lead is consolidating opinions...",
                                ja: "企画リードが意見を集約中...",
                                zh: "规划负责人正在汇总意见...",
                              })}
                            </p>
                          );
                        }
                        const pickOptions = getReviewPickOptions(item);
                        const skipOption = getReviewSkipOption(item);
                        const selected = reviewPickSelections[item.id] ?? [];
                        const selectedCount = selected.length;
                        const draft = reviewPickDrafts[item.id] ?? "";
                        const isItemBusy = Boolean(busyKey?.startsWith(`${item.id}:`));
                        return (
                          <div className="space-y-2">
                            {pickOptions.map((option) => {
                              const selectedFlag = selected.includes(option.number);
                              return (
                                <button
                                  key={`${item.id}:${option.number}`}
                                  type="button"
                                  onClick={() => toggleReviewPick(item.id, option.number)}
                                  disabled={isItemBusy}
                                  className={`decision-inbox-option w-full rounded-md px-2.5 py-1.5 text-left text-xs transition disabled:cursor-not-allowed disabled:opacity-60${selectedFlag ? " decision-inbox-option-active" : ""}`}
                                >
                                  {`${option.number}. ${option.label}`}
                                </button>
                              );
                            })}
                            <p className="text-[11px] text-slate-400">
                              {t({
                                ko: `선택 항목: ${selectedCount}건`,
                                en: `Selected: ${selectedCount} item(s)`,
                                ja: `選択項目: ${selectedCount}件`,
                                zh: `已选项: ${selectedCount} 项`,
                              })}
                            </p>
                            <textarea
                              value={draft}
                              onChange={(event) => setReviewDraft(item.id, event.target.value)}
                              rows={2}
                              placeholder={t({
                                ko: "추가 의견이 있으면 입력해 주세요. (선택)",
                                en: "Enter extra notes if needed. (Optional)",
                                ja: "追加意見があれば入力してください。（任意）",
                                zh: "如有补充意见请填写。（可选）",
                              })}
                              className="w-full resize-y rounded-lg border border-slate-600 bg-slate-950 px-3 py-2 text-xs text-slate-100 placeholder:text-slate-500 focus:border-indigo-400 focus:outline-none"
                            />
                            <div className="flex flex-wrap items-center justify-end gap-2">
                              {skipOption ? (
                                <button
                                  type="button"
                                  onClick={() => handleSkipReviewRound(item)}
                                  disabled={isItemBusy}
                                  className="decision-round-skip rounded-md px-3 py-1.5 text-xs font-semibold transition disabled:cursor-not-allowed disabled:opacity-60"
                                >
                                  {isItemBusy
                                    ? t({ ko: "전송 중...", en: "Sending...", ja: "送信中...", zh: "发送中..." })
                                    : `${skipOption.number}. ${skipOption.label}`}
                                </button>
                              ) : null}
                              <button
                                type="button"
                                onClick={() => handleSubmitReviewPick(item)}
                                disabled={isItemBusy}
                                className="decision-round-submit rounded-md px-3 py-1.5 text-xs font-semibold transition disabled:cursor-not-allowed disabled:opacity-60"
                              >
                                {isItemBusy
                                  ? t({ ko: "전송 중...", en: "Sending...", ja: "送信中...", zh: "发送中..." })
                                  : t({
                                      ko: "선택 항목 진행",
                                      en: "Run Selected",
                                      ja: "選択項目で進行",
                                      zh: "按所选项执行",
                                    })}
                              </button>
                            </div>
                          </div>
                        );
                      })()
                    ) : item.options.length > 0 ? (
                      item.options.map((option) => {
                        const key = `${item.id}:${option.number}`;
                        const isBusy = busyKey === key;
                        return (
                          <button
                            key={key}
                            type="button"
                            onClick={() => handleOptionClick(item, option.number, option.action)}
                            disabled={isBusy}
                            className="decision-inbox-option w-full rounded-md px-2.5 py-1.5 text-left text-xs transition disabled:cursor-not-allowed disabled:opacity-60"
                          >
                            {isBusy
                              ? t({ ko: "전송 중...", en: "Sending...", ja: "送信中...", zh: "发送中..." })
                              : `${option.number}. ${option.label}`}
                          </button>
                        );
                      })
                    ) : (
                      <p className="rounded-md border border-slate-700/70 bg-slate-900/50 px-2.5 py-2 text-xs text-slate-400">
                        {item.kind === "project_review_ready"
                          ? t({
                              ko: "기획팀장 의견 취합중...",
                              en: "Planning lead is consolidating opinions...",
                              ja: "企画リードが意見を集約中...",
                              zh: "规划负责人正在汇总意见...",
                            })
                          : t({
                              ko: "선택지 준비 중...",
                              en: "Options are being prepared...",
                              ja: "選択肢を準備中...",
                              zh: "正在准备选项...",
                            })}
                      </p>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
        {followupItem ? (
          <div className="border-t border-slate-700/60 bg-slate-900/90 px-4 py-3">
            <p className="mb-2 text-xs font-semibold text-slate-200">
              {t({
                ko: "추가요청사항 입력",
                en: "Additional Follow-up Request",
                ja: "追加要請内容の入力",
                zh: "输入追加请求事项",
              })}
            </p>
            <textarea
              value={followupDraft}
              onChange={(event) => setFollowupDraft(event.target.value)}
              placeholder={t({
                ko: "요청사항을 입력해 주세요.",
                en: "Enter your request details.",
                ja: "要請内容を入力してください。",
                zh: "请输入请求详情。",
              })}
              rows={3}
              className="w-full resize-y rounded-lg border border-slate-600 bg-slate-950 px-3 py-2 text-xs text-slate-100 placeholder:text-slate-500 focus:border-indigo-400 focus:outline-none"
            />
            <div className="mt-2 flex items-center justify-end gap-2">
              <button
                type="button"
                onClick={handleCancelFollowup}
                disabled={isFollowupSubmitting}
                className="rounded-md border border-slate-600 px-3 py-1.5 text-xs text-slate-300 transition hover:bg-slate-800 disabled:cursor-not-allowed disabled:opacity-60"
              >
                {t({ ko: "취소", en: "Cancel", ja: "キャンセル", zh: "取消" })}
              </button>
              <button
                type="button"
                onClick={handleSubmitFollowup}
                disabled={!canSubmitFollowup}
                className="decision-followup-submit rounded-md px-3 py-1.5 text-xs font-semibold transition disabled:cursor-not-allowed disabled:opacity-60"
              >
                {isFollowupSubmitting
                  ? t({ ko: "전송 중...", en: "Sending...", ja: "送信中...", zh: "发送中..." })
                  : t({ ko: "요청 등록", en: "Submit Request", ja: "要請登録", zh: "提交请求" })}
              </button>
            </div>
          </div>
        ) : null}
      </div>
    </div>
  );
}

import {useEffect} from "react";
import { useState, useRef, useMemo, useCallback } from "react";
import type { DecisionInboxItem } from "./components/chat/decision-inbox";
import { useWebSocket } from "./hooks/useWebSocket";
import type {
  Department,
  Agent,
  Task,
  Message,
  CompanyStats,
  CompanySettings,
  CliStatusMap,
  SubTask,
  MeetingPresence,
  SubAgent,
  CrossDeptDelivery,
  CeoOfficeCall,
  OfficePackProfile,
  RoomTheme,
  WorkflowPackKey,
} from "./types";
import type { TaskReportDetail } from "./api";
import * as api from "./api";
import { detectBrowserLanguage, normalizeLanguage } from "./i18n";
import { useTheme } from "./ThemeContext";
import { ROOM_THEMES_STORAGE_KEY, UPDATE_BANNER_DISMISS_STORAGE_KEY } from "./app/constants";
import {
  detectRuntimeOs,
  isForceUpdateBannerEnabled,
  mergeSettingsWithDefaults,
  readStoredRoomThemes,
} from "./app/utils";
import type { OAuthCallbackResult, RuntimeOs, RoomThemeMap, TaskPanelTab, View } from "./app/types";
import { useRealtimeSync } from "./app/useRealtimeSync";
import { useAppLabels } from "./app/useAppLabels";
import AppLoadingScreen from "./app/AppLoadingScreen";
import AppMainLayout from "./app/AppMainLayout";
import AppOverlays from "./app/AppOverlays";
import { useAppActions } from "./app/useAppActions";
import { useActiveMeetingTaskId } from "./app/useActiveMeetingTaskId";
import { useUpdateStatusPolling } from "./app/useUpdateStatusPolling";
import { useAppViewEffects } from "./app/useAppViewEffects";
import { useAppBootstrapData } from "./app/useAppBootstrapData";
import { useLiveSyncScheduler } from "./app/useLiveSyncScheduler";
import { resolvePackAgentViews, resolvePackDepartmentsForDisplay } from "./app/office-pack-display";
import {
  buildOfficePackPresentation,
  buildOfficePackStarterAgents,
  getOfficePackMeta,
  normalizeOfficeWorkflowPack,
  resolveOfficePackSeedProvider,
} from "./app/office-workflow-pack";

export type { OAuthCallbackResult } from "./app/types";

export default function App() {
  const { theme, toggleTheme } = useTheme();
  const initialRoomThemes = useMemo(() => readStoredRoomThemes(), []);
  const hasLocalRoomThemesRef = useRef<boolean>(initialRoomThemes.hasStored);

  const [view, setView] = useState<View>("office");
  const [departments, setDepartments] = useState<Department[]>([]);
  const [agents, setAgents] = useState<Agent[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [messages, setMessages] = useState<Message[]>([]);
  const [stats, setStats] = useState<CompanyStats | null>(null);
  const [settings, setSettings] = useState<CompanySettings>(() =>
    mergeSettingsWithDefaults({ language: detectBrowserLanguage() }),
  );
  const [cliStatus, setCliStatus] = useState<CliStatusMap | null>(null);
  const [subAgents, setSubAgents] = useState<SubAgent[]>([]);
  const [subtasks, setSubtasks] = useState<SubTask[]>([]);

  const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
  const [chatAgent, setChatAgent] = useState<Agent | null>(null);
  const [showChat, setShowChat] = useState(false);
  useEffect(()=>{const ready=()=>window.parent.postMessage({kind:'office-native-room-ready'},location.origin);const listener=(event:MessageEvent)=>{if(event.origin!==location.origin||event.source!==window.parent)return;if(event.data?.kind==='office-native-room-open'){setChatAgent(null);setShowChat(true);}if(event.data?.kind==='office-native-room-check')ready();};window.addEventListener('message',listener);ready();return()=>window.removeEventListener('message',listener);},[]);
  const [taskPanel, setTaskPanel] = useState<{ taskId: string; tab: TaskPanelTab } | null>(null);
  const [loading, setLoading] = useState(true);
  const [unreadAgentIds, setUnreadAgentIds] = useState<Set<string>>(new Set());
  const [crossDeptDeliveries, setCrossDeptDeliveries] = useState<CrossDeptDelivery[]>([]);
  const [ceoOfficeCalls, setCeoOfficeCalls] = useState<CeoOfficeCall[]>([]);
  const [meetingPresence, setMeetingPresence] = useState<MeetingPresence[]>([]);
  const [oauthResult, setOauthResult] = useState<OAuthCallbackResult | null>(null);
  const [taskReport, setTaskReport] = useState<TaskReportDetail | null>(null);
  const [showReportHistory, setShowReportHistory] = useState(false);
  const [showAgentStatus, setShowAgentStatus] = useState(false);
  const [showRoomManager, setShowRoomManager] = useState(false);
  const [showDecisionInbox, setShowDecisionInbox] = useState(false);
  const [decisionInboxLoading, setDecisionInboxLoading] = useState(false);
  const [decisionInboxItems, setDecisionInboxItems] = useState<DecisionInboxItem[]>([]);
  const [decisionReplyBusyKey, setDecisionReplyBusyKey] = useState<string | null>(null);
  const [activeRoomThemeTargetId, setActiveRoomThemeTargetId] = useState<string | null>(null);
  const [customRoomThemes, setCustomRoomThemes] = useState<RoomThemeMap>(() => initialRoomThemes.themes);
  const [mobileNavOpen, setMobileNavOpen] = useState(false);
  const [mobileHeaderMenuOpen, setMobileHeaderMenuOpen] = useState(false);
  const [officePackBootstrappingLabel, setOfficePackBootstrappingLabel] = useState<string | null>(null);
  const [runtimeOs] = useState<RuntimeOs>(() => detectRuntimeOs());
  const [forceUpdateBanner] = useState<boolean>(() => isForceUpdateBannerEnabled());
  const [updateStatus, setUpdateStatus] = useState<api.UpdateStatus | null>(null);
  const [dismissedUpdateVersion, setDismissedUpdateVersion] = useState<string>(() => {
    if (typeof window === "undefined") return "";
    return window.localStorage.getItem(UPDATE_BANNER_DISMISS_STORAGE_KEY) ?? "";
  });
  const [streamingMessage, setStreamingMessage] = useState<{
    message_id: string;
    agent_id: string;
    agent_name: string;
    agent_avatar: string;
    content: string;
  } | null>(null);

  const viewRef = useRef<View>("office");
  viewRef.current = view;
  const agentsRef = useRef<Agent[]>(agents);
  agentsRef.current = agents;
  const tasksRef = useRef<Task[]>(tasks);
  tasksRef.current = tasks;
  const subAgentsRef = useRef<SubAgent[]>(subAgents);
  subAgentsRef.current = subAgents;
  const codexThreadToSubAgentIdRef = useRef<Map<string, string>>(new Map());
  const codexThreadBindingTsRef = useRef<Map<string, number>>(new Map());
  const subAgentStreamTailRef = useRef<Map<string, string>>(new Map());
  const activeChatRef = useRef<{ showChat: boolean; agentId: string | null }>({ showChat: false, agentId: null });
  activeChatRef.current = { showChat, agentId: chatAgent?.id ?? null };
  const officePackBootstrapReqRef = useRef(0);

  const readHydratedPackSet = (source: CompanySettings): Set<string> => {
    const raw = source.officePackHydratedPacks;
    if (!Array.isArray(raw)) return new Set<string>();
    return new Set(raw.map((value) => String(value ?? "").trim()).filter((value) => value.length > 0));
  };

  const getPackLabelByLanguage = (packKey: WorkflowPackKey, language: string): string => {
    const label = getOfficePackMeta(packKey).label;
    const lang = normalizeLanguage(language);
    if (lang === "ko") return label.ko || label.en;
    if (lang === "ja") return label.ja || label.en;
    if (lang === "zh") return label.zh || label.en;
    return label.en;
  };

  const maybeBuildSeedProfileForPack = (
    packKey: WorkflowPackKey,
    sourceSettings: CompanySettings,
  ): OfficePackProfile | null => {
    if (packKey === "development") return null;

    const existingProfile = sourceSettings.officePackProfiles?.[packKey];
    if (existingProfile?.departments?.length && existingProfile?.agents?.length) {
      return null;
    }

    const locale = normalizeLanguage(sourceSettings.language) as "ko" | "en" | "ja" | "zh";
    const presentation = buildOfficePackPresentation({
      packKey,
      locale,
      departments,
      agents,
      customRoomThemes,
    });
    if (presentation.departments.length <= 0) return null;

    const starterDrafts = buildOfficePackStarterAgents({
      packKey,
      departments: presentation.departments,
      targetCount: 8,
      locale,
    });
    if (starterDrafts.length <= 0) return null;

    const now = Date.now();
    const seededAgents: Agent[] = starterDrafts.map((draft, index) => ({
      id: `${packKey}-seed-${index + 1}`,
      name: draft.name,
      name_ko: draft.name_ko,
      name_ja: draft.name_ja,
      name_zh: draft.name_zh,
      department_id: draft.department_id,
      role: draft.role,
      acts_as_planning_leader: draft.acts_as_planning_leader,
      cli_provider: resolveOfficePackSeedProvider({
        packKey,
        departmentId: draft.department_id,
        role: draft.role,
        seedIndex: index + 1,
        seedOrderInDepartment: draft.seed_order_in_department,
      }),
      avatar_emoji: draft.avatar_emoji,
      sprite_number: draft.sprite_number,
      personality: draft.personality,
      status: "idle",
      current_task_id: null,
      stats_tasks_done: 0,
      stats_xp: 0,
      created_at: now + index,
    }));

    return {
      departments: presentation.departments,
      agents: seededAgents,
      updated_at: now,
    };
  };

  const handleOfficeWorkflowPackChange = (packKey: WorkflowPackKey) => {
    const previousPack = settings.officeWorkflowPack ?? "development";
    const previousProfiles = settings.officePackProfiles;
    const currentHydratedSet = readHydratedPackSet(settings);
    const shouldShowBootstrap = packKey !== "development" && !currentHydratedSet.has(packKey);
    const seedProfile = shouldShowBootstrap ? maybeBuildSeedProfileForPack(packKey, settings) : null;
    const nextOfficePackProfiles = seedProfile
      ? {
          ...(settings.officePackProfiles ?? {}),
          [packKey]: seedProfile,
        }
      : settings.officePackProfiles;
    const patchPayload: Record<string, unknown> = { officeWorkflowPack: packKey };
    if (seedProfile) {
      patchPayload.officePackProfiles = nextOfficePackProfiles;
    }
    const reqId = ++officePackBootstrapReqRef.current;
    if (shouldShowBootstrap) {
      setOfficePackBootstrappingLabel(getPackLabelByLanguage(packKey, settings.language));
    } else {
      setOfficePackBootstrappingLabel(null);
    }
    setSettings((prev) => ({
      ...prev,
      officeWorkflowPack: packKey,
      ...(seedProfile ? { officePackProfiles: nextOfficePackProfiles } : {}),
    }));
    api
      .saveSettingsPatch(patchPayload)
      .then(async () => {
        const [nextDepartments, nextAgents, nextSettingsRaw] = await Promise.all([
          api.getDepartments({ workflowPackKey: packKey }),
          api.getAgents({ includeSeed: packKey !== "development" }),
          api.getSettings(),
        ]);
        setDepartments(nextDepartments);
        setAgents(nextAgents);
        setSettings(mergeSettingsWithDefaults(nextSettingsRaw));
        const clearNotice = () => {
          if (officePackBootstrapReqRef.current !== reqId) return;
          setOfficePackBootstrappingLabel(null);
        };
        if (shouldShowBootstrap) {
          setTimeout(clearNotice, 650);
        } else {
          clearNotice();
        }
      })
      .catch((error) => {
        console.error("Save office workflow pack failed:", error);
        if (officePackBootstrapReqRef.current === reqId) {
          setOfficePackBootstrappingLabel(null);
        }
        setSettings((prev) =>
          prev.officeWorkflowPack === packKey
            ? {
                ...prev,
                officeWorkflowPack: previousPack,
                ...(seedProfile ? { officePackProfiles: previousProfiles } : {}),
              }
            : prev,
        );
      });
  };

  const { connected, on } = useWebSocket();
  const shouldIncludeSeedAgents = useCallback(
    () => normalizeOfficeWorkflowPack(settings.officeWorkflowPack ?? "development") !== "development",
    [settings.officeWorkflowPack],
  );
  const scheduleLiveSync = useLiveSyncScheduler({
    setTasks,
    setAgents,
    setStats,
    setDecisionInboxItems,
    shouldIncludeSeedAgents,
  });

  useAppBootstrapData({
    initialRoomThemes,
    hasLocalRoomThemesRef,
    setDepartments,
    setAgents,
    setTasks,
    setStats,
    setSettings,
    setSubtasks,
    setMeetingPresence,
    setDecisionInboxItems,
    setCustomRoomThemes,
    setLoading,
  });

  useUpdateStatusPolling(setUpdateStatus);
  useAppViewEffects({
    view,
    cliStatus,
    setView,
    setOauthResult,
    setCliStatus,
    setMobileNavOpen,
    setMeetingPresence,
  });

  useRealtimeSync({
    on,
    scheduleLiveSync,
    agentsRef,
    tasksRef,
    subAgentsRef,
    viewRef,
    activeChatRef,
    codexThreadToSubAgentIdRef,
    codexThreadBindingTsRef,
    subAgentStreamTailRef,
    setAgents,
    setMessages,
    setUnreadAgentIds,
    setTaskReport,
    setCrossDeptDeliveries,
    setCeoOfficeCalls,
    setMeetingPresence,
    setSubtasks,
    setSubAgents,
    setStreamingMessage,
  });

  const actions = useAppActions({
    agents,
    settings,
    scheduleLiveSync,
    setSettings,
    setAgents,
    setDepartments,
    setTasks,
    setStats,
    setMessages,
    setChatAgent,
    setShowChat,
    setUnreadAgentIds,
    setShowDecisionInbox,
    setDecisionInboxLoading,
    setDecisionInboxItems,
    setDecisionReplyBusyKey,
    setCliStatus,
  });

  const activeMeetingTaskId = useActiveMeetingTaskId(meetingPresence);

  const labels = useAppLabels({
    view,
    settings,
    departments,
    theme,
    runtimeOs,
    forceUpdateBanner,
    updateStatus,
    dismissedUpdateVersion,
  });

  const activePackKey = normalizeOfficeWorkflowPack(settings.officeWorkflowPack ?? "development");
  const activePackProfile =
    activePackKey === "development" ? null : (settings.officePackProfiles?.[activePackKey] ?? null);
  const overlayDepartments = useMemo(
    () =>
      resolvePackDepartmentsForDisplay({
        packKey: activePackKey,
        globalDepartments: departments,
        packDepartments: activePackProfile?.departments ?? null,
      }),
    [activePackKey, activePackProfile?.departments, departments],
  );
  const { mergedAgents: overlayAgents } = useMemo(
    () =>
      resolvePackAgentViews({
        packKey: activePackKey,
        globalAgents: agents,
        packAgents: activePackProfile?.agents ?? null,
      }),
    [activePackKey, activePackProfile?.agents, agents],
  );

  if (loading) {
    return (
      <AppLoadingScreen language={labels.uiLanguage} title={labels.loadingTitle} subtitle={labels.loadingSubtitle} />
    );
  }

  return (
    <AppMainLayout
      connected={connected}
      view={view}
      setView={setView}
      departments={departments}
      agents={agents}
      stats={stats}
      tasks={tasks}
      subtasks={subtasks}
      subAgents={subAgents}
      meetingPresence={meetingPresence}
      settings={settings}
      cliStatus={cliStatus}
      oauthResult={oauthResult}
      labels={labels}
      mobileNavOpen={mobileNavOpen}
      setMobileNavOpen={setMobileNavOpen}
      mobileHeaderMenuOpen={mobileHeaderMenuOpen}
      setMobileHeaderMenuOpen={setMobileHeaderMenuOpen}
      theme={theme}
      toggleTheme={toggleTheme}
      decisionInboxLoading={decisionInboxLoading}
      decisionInboxCount={decisionInboxItems.length}
      activeMeetingTaskId={activeMeetingTaskId}
      unreadAgentIds={unreadAgentIds}
      crossDeptDeliveries={crossDeptDeliveries}
      ceoOfficeCalls={ceoOfficeCalls}
      customRoomThemes={customRoomThemes}
      activeRoomThemeTargetId={activeRoomThemeTargetId}
      onCrossDeptDeliveryProcessed={(id) => setCrossDeptDeliveries((prev) => prev.filter((d) => d.id !== id))}
      onCeoOfficeCallProcessed={(id) => setCeoOfficeCalls((prev) => prev.filter((d) => d.id !== id))}
      onOpenActiveMeetingMinutes={(taskId) => setTaskPanel({ taskId, tab: "minutes" })}
      onSelectAgent={setSelectedAgent}
      onSelectDepartment={(department) => {
        const candidateAgents = overlayAgents;
        const leader =
          candidateAgents.find((agent) => agent.department_id === department.id && agent.role === "team_leader") ??
          (department.id === "planning"
            ? candidateAgents.find(
                (agent) => agent.role === "team_leader" && Number(agent.acts_as_planning_leader ?? 0) === 1,
              )
            : undefined);
        if (leader) actions.handleOpenChat(leader);
      }}
      onCreateTask={actions.handleCreateTask}
      onUpdateTask={actions.handleUpdateTask}
      onDeleteTask={actions.handleDeleteTask}
      onAssignTask={actions.handleAssignTask}
      onRunTask={actions.handleRunTask}
      onStopTask={actions.handleStopTask}
      onPauseTask={actions.handlePauseTask}
      onResumeTask={actions.handleResumeTask}
      onOpenTerminal={(taskId) => setTaskPanel({ taskId, tab: "terminal" })}
      onOpenMeetingMinutes={(taskId) => setTaskPanel({ taskId, tab: "minutes" })}
      onAgentsChange={actions.handleAgentsChange}
      activeOfficeWorkflowPack={settings.officeWorkflowPack ?? "development"}
      onChangeOfficeWorkflowPack={handleOfficeWorkflowPackChange}
      onSaveSettings={actions.handleSaveSettings}
      onRefreshCli={actions.handleRefreshCli}
      onOauthResultClear={() => setOauthResult(null)}
      onOpenDecisionInbox={actions.handleOpenDecisionInbox}
      onOpenAgentStatus={() => setShowAgentStatus(true)}
      onOpenReportHistory={() => setShowReportHistory(true)}
      onOpenAnnouncement={actions.handleOpenAnnouncement}
      onOpenRoomManager={() => setShowRoomManager(true)}
      onDismissAutoUpdateNotice={actions.handleDismissAutoUpdateNotice}
      onDismissUpdate={() => {
        const latest = labels.effectiveUpdateStatus?.latest_version ?? "";
        setDismissedUpdateVersion(latest);
        if (typeof window !== "undefined") {
          window.localStorage.setItem(UPDATE_BANNER_DISMISS_STORAGE_KEY, latest);
        }
      }}
      officePackBootstrappingLabel={officePackBootstrappingLabel}
    >
      <AppOverlays
        showChat={showChat}
        chatAgent={chatAgent}
        messages={messages}
        agents={overlayAgents}
        streamingMessage={streamingMessage}
        onSendMessage={actions.handleSendMessage}
        onSendAnnouncement={actions.handleSendAnnouncement}
        onSendDirective={actions.handleSendDirective}
        onClearMessages={actions.handleClearMessages}
        onCloseChat={() => setShowChat(false)}
        showDecisionInbox={showDecisionInbox}
        decisionInboxLoading={decisionInboxLoading}
        decisionInboxItems={decisionInboxItems}
        decisionReplyBusyKey={decisionReplyBusyKey}
        uiLanguage={labels.uiLanguage}
        onCloseDecisionInbox={() => setShowDecisionInbox(false)}
        onRefreshDecisionInbox={() => {
          void actions.loadDecisionInbox();
        }}
        onReplyDecisionOption={actions.handleReplyDecisionOption}
        onOpenDecisionChat={actions.handleOpenDecisionChat}
        selectedAgent={selectedAgent}
        activeOfficeWorkflowPack={settings.officeWorkflowPack ?? "development"}
        departments={overlayDepartments}
        tasks={tasks}
        subAgents={subAgents}
        subtasks={subtasks}
        onCloseSelectedAgent={() => setSelectedAgent(null)}
        onChatFromAgentDetail={(agent) => {
          setSelectedAgent(null);
          actions.handleOpenChat(agent);
        }}
        onAssignTaskFromAgentDetail={() => {
          setSelectedAgent(null);
          setView("tasks");
        }}
        onOpenTerminalFromAgentDetail={(taskId) => {
          setSelectedAgent(null);
          setTaskPanel({ taskId, tab: "terminal" });
        }}
        onAgentUpdated={() => {
          api
            .getSettings()
            .then(async (nextSettingsRaw) => {
              const nextSettings = mergeSettingsWithDefaults(nextSettingsRaw);
              const activePack = nextSettings.officeWorkflowPack ?? "development";
              const nextAgents = await api.getAgents({ includeSeed: activePack !== "development" });
              setAgents(nextAgents);
              setSettings(nextSettings);

              if (!selectedAgent) return;
              const fromAgents = nextAgents.find((agent) => agent.id === selectedAgent.id);
              if (fromAgents) {
                setSelectedAgent(fromAgents);
                return;
              }

              const profilePackKey = nextSettings.officeWorkflowPack ?? "development";
              const fromPackProfile = nextSettings.officePackProfiles?.[profilePackKey]?.agents?.find(
                (agent) => agent.id === selectedAgent.id,
              );
              if (fromPackProfile) {
                setSelectedAgent(fromPackProfile);
              }
            })
            .catch(console.error);
        }}
        taskPanel={taskPanel}
        onCloseTaskPanel={() => setTaskPanel(null)}
        taskReport={taskReport}
        onCloseTaskReport={() => setTaskReport(null)}
        showReportHistory={showReportHistory}
        onCloseReportHistory={() => setShowReportHistory(false)}
        showAgentStatus={showAgentStatus}
        onCloseAgentStatus={() => setShowAgentStatus(false)}
        showRoomManager={showRoomManager}
        roomManagerDepartments={labels.roomManagerDepartments}
        customRoomThemes={customRoomThemes}
        onActiveRoomThemeTargetIdChange={setActiveRoomThemeTargetId}
        onRoomThemeChange={(themes) => {
          setCustomRoomThemes(themes as RoomThemeMap);
          hasLocalRoomThemesRef.current = true;
          try {
            window.localStorage.setItem(ROOM_THEMES_STORAGE_KEY, JSON.stringify(themes));
          } catch {
            // ignore quota errors
          }
          api.saveRoomThemes(themes as Record<string, RoomTheme>).catch((error) => {
            console.error("Save room themes failed:", error);
          });
        }}
        onCloseRoomManager={() => {
          setShowRoomManager(false);
          setActiveRoomThemeTargetId(null);
        }}
      />
    </AppMainLayout>
  );
}

